        Seed("external-object-impact", "Ходовая часть", "Удар постороннего предмета под локомотивом", "После удара появились шум, утечка или изменение поведения ходовой части.", "метельник, тележка, трубопроводы", "удар, скрежет, утечка", "повреждение тормозов или ходовой части"),
    )

    val scenarios: List<DiagnosticScenario> = seeds.map(::toScenario)

    private fun toScenario(seed: Seed): DiagnosticScenario {
        val prefix = seed.id
        return DiagnosticScenario(
            id = seed.id,
            category = seed.category,
            title = seed.title,
            summary = seed.summary,
            severity = DiagnosticSeverity.RESTRICT_OPERATION,
            immediateActions = listOf(
                "Убрать тяговую или иную нагрузку, если это требуется для безопасного состояния.",
                "Зафиксировать секцию, режим, показания приборов, лампы, звук, запах и момент появления признака.",
                "Не выполнять повторные включения при защитном отключении, нагреве, дыме, дуге или механическом повреждении."
            ),
            dangerSigns = listOf(seed.danger, "Дым, огонь, дуга, резкий запах, опасный нагрев или повторное действие защиты."),
            observableSigns = seed.signs.split(", "),
            questions = listOf(
                DiagnosticQuestion(
                    key = "$prefix-scope",
                    text = "Признак относится только к одной секции, тележке или группе?",
                    yesMeaning = "Локальная причина вероятнее общей; точно указать место в докладе.",
                    noMeaning = "Проверять общую команду, питание, воздух или связанную систему без обхода защит.",
                    yesNextKey = "$prefix-repeat", noNextKey = "$prefix-repeat", unknownNextKey = "$prefix-repeat",
                    yesCandidateCauseIds = listOf("$prefix-local"), noCandidateCauseIds = listOf("$prefix-common")
                ),
                DiagnosticQuestion(
                    key = "$prefix-repeat",
                    text = "Признак устойчиво повторяется при одинаковом безопасном наблюдении?",
                    yesMeaning = "Отказ считать устойчивым; повторные воздействия прекратить и готовить доклад.",
                    noMeaning = "Записать условия кратковременного появления; отсутствие повтора не доказывает исправность.",
                    yesNextKey = "$prefix-danger", noNextKey = "$prefix-danger", unknownNextKey = "$prefix-danger",
                    yesCandidateCauseIds = listOf("$prefix-device"), noCandidateCauseIds = listOf("$prefix-intermittent")
                ),
                DiagnosticQuestion(
                    key = "$prefix-danger",
                    text = "Есть опасный нагрев, дым, дуга, утечка, разрушение или защитное отключение?",
                    yesMeaning = "Диагностические действия прекратить; обеспечить безопасное состояние и доложить.",
                    noMeaning = "Продолжать только разрешённые наблюдения по карточке и местной инструкции.",
                    yesNextKey = DiagnosticRepository.END_OF_FLOW, noNextKey = DiagnosticRepository.END_OF_FLOW, unknownNextKey = DiagnosticRepository.END_OF_FLOW,
                    yesCandidateCauseIds = listOf("$prefix-dangerous"), unknownCandidateCauseIds = listOf("$prefix-device")
                )
            ),
            diagnosticCauses = listOf(
                DiagnosticCause("$prefix-local", "Локальный отказ", "Признак ограничен одним аппаратом, группой или секцией."),
                DiagnosticCause("$prefix-common", "Общая причина", "Одновременно затронуты несколько связанных потребителей или секций."),
                DiagnosticCause("$prefix-device", "Устойчивый отказ оборудования", "Признак повторяется при одинаковых условиях; подтверждение требует проверки по схеме."),
                DiagnosticCause("$prefix-intermittent", "Нестабильный контакт или условие", "Кратковременный характер требует фиксации режима и обратной связи."),
                DiagnosticCause("$prefix-dangerous", "Аварийный признак", "Дальнейшие действия прекращаются до решения по установленному порядку.")
            ),
            probableCauses = listOf(
                "Локальная неисправность одного из элементов: ${seed.equipment}.",
                "Нарушение питания, команды, пневматического пути, соединения или обратной сигнализации.",
                "Отличие схемы конкретной секции, модернизация либо неверная интерпретация индикации."
            ),
            checks = listOf(
                DiagnosticCheck("Наблюдение из кабины", "Сопоставить команду, индикацию и показания приборов по секциям.", "Состояния согласованы, новых опасных признаков нет.", "Зафиксировать первое расхождение и перейти к безопасной ветке.", DiagnosticActionLevel.CAB),
                DiagnosticCheck("Внешний осмотр", "После безопасной остановки выполнить только разрешённый внешний осмотр без вскрытия и приближения к опасным частям.", "Нет повреждения, нагрева, дыма, утечки или постороннего предмета.", "Действия прекратить, оградить опасную зону и доложить.", DiagnosticActionLevel.SAFE_STOP),
                DiagnosticCheck("Проверка по схеме", "Проверить цепи и аппарат по принципиальной/монтажной схеме конкретного исполнения.", "Причина подтверждена измерением и устранена по технологии ремонта.", "Только допущенный персонал; не подавать напряжение и не обходить защиты ради поиска.", DiagnosticActionLevel.AUTHORIZED_ONLY)
            ),
            prohibited = listOf(
                "Шунтировать блокировки и защиты, удерживать аппарат вручную или ставить временные перемычки.",
                "Открывать ВВК, выходить на крышу либо вмешиваться в оборудование под напряжением.",
                "Многократно повторять включение после неизвестной защиты, дыма, дуги, запаха или нагрева."
            ),
            stopConditions = listOf(seed.danger, "Причина затрагивает высоковольтную, тормозную или ходовую безопасность и не подтверждена."),
            reportFields = listOf("локомотив и секция", "режим и момент появления", "приборы и лампы", "звук/запах/нагрев", "выполненные безопасные наблюдения", "обратная связь"),
            relatedEquipment = seed.equipment.split(", "),
            systemExplanation = listOf("Наблюдение связывается с системой: ${seed.equipment}.", "Первое расхождение между командой, индикацией и фактическим состоянием задаёт границу дальнейшего поиска."),
            operationalConsequences = listOf(seed.danger),
            trainingNotes = listOf("Дерево сначала отделяет локальный отказ от общей причины, затем устойчивый отказ от кратковременного и в конце проверяет аварийные признаки."),
            feedbackPrompts = listOf("Что изменилось после снятия нагрузки?", "На какой секции и в каком режиме признак появился снова?"),
            informationConfidence = InformationConfidence.REQUIRES_VARIANT_CHECK,
            sourceNote = "Руководства и учебные материалы по ВЛ80С; конкретные обозначения и допустимые действия сверять по схеме исполнения и местной инструкции."
        )
    }
}
